-- Converted: CREATE UNIQUE secondary index sales.ix_account_customer (customer_id) -> pre-check block that fails if SALES."ACCOUNT" already holds duplicate CUSTOMER_ID values
-- Reason: Teradata refuses to build a unique index over duplicate keys; Snowflake does not enforce UNIQUE, so the check keeps the creation-time error behaviour. NULL is counted as a key value because a Teradata unique index admits at most one NULL.
EXECUTE IMMEDIATE $$
DECLARE
    dup_count NUMBER(38,0) DEFAULT 0;
    duplicate_unique_key EXCEPTION (-20801, 'Duplicate CUSTOMER_ID values in SALES.ACCOUNT; unique index IX_ACCOUNT_CUSTOMER cannot be created');
BEGIN
    SELECT COUNT(*) INTO :dup_count
    FROM (
        SELECT a.CUSTOMER_ID
        FROM SALES."ACCOUNT" a
        GROUP BY a.CUSTOMER_ID
        HAVING COUNT(*) > 1
    ) d;
    IF (dup_count > 0) THEN
        RAISE duplicate_unique_key;
    END IF;
    RETURN NULL;
END;
$$;

-- Converted: uniqueness of CUSTOMER_ID -> informational UNIQUE constraint named IX_ACCOUNT_CUSTOMER
-- Reason: Keeps the source name and documents the key for tools and the optimizer; Snowflake does NOT enforce UNIQUE on standard tables (only NOT NULL is enforced).
ALTER TABLE SALES."ACCOUNT" ADD CONSTRAINT IX_ACCOUNT_CUSTOMER UNIQUE (CUSTOMER_ID);

-- Converted: unique secondary-index access path on CUSTOMER_ID -> search optimization EQUALITY(CUSTOMER_ID)
-- Reason: Index DDL applies only to hybrid tables; search optimization is the documented replacement for selective point lookups on a unique column, and the table clustering key is used by SALES.HIX_ACCOUNT.
ALTER TABLE SALES."ACCOUNT" ADD SEARCH OPTIMIZATION ON EQUALITY(CUSTOMER_ID);

-- Converted: CREATE PROCEDURE sales.post_transfer(IN p_from BIGINT, IN p_to BIGINT, IN p_amount DECIMAL(12, 2)) -> CREATE PROCEDURE SALES.POST_TRANSFER(P_FROM NUMBER(19,0), P_TO NUMBER(19,0), P_AMOUNT NUMBER(12,2)) RETURNS VARCHAR LANGUAGE SQL
-- Reason: Snowflake Scripting procedure with exact NUMBER parameter types; RETURNS is mandatory, so RETURN NULL stands in for no return value. P_AMOUNT is kept in the signature even though the source body never uses it. Plain CREATE keeps the error if it already exists.
-- Converted: default SQL SECURITY (DEFINER) -> EXECUTE AS OWNER
-- Reason: Closest Snowflake equivalent of definer's rights; Snowflake requires the clause to be explicit.
CREATE PROCEDURE SALES.POST_TRANSFER(P_FROM NUMBER(19,0), P_TO NUMBER(19,0), P_AMOUNT NUMBER(12,2))
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS
$$
DECLARE
    dup_count NUMBER(38,0) DEFAULT 0;
    duplicate_transfer EXCEPTION (-20802, 'Duplicate row in SET table SALES.TRANSFER');
    duplicate_audit EXCEPTION (-20803, 'Duplicate row in SET table SALES.AUDIT_LOG (EVENT_ID 2, EVENT_TYPE TRANSFER)');
BEGIN
    -- Converted: SET-table duplicate-row error on SALES.TRANSFER -> NULL-safe existence check that raises -20802
    -- Reason: SALES.TRANSFER was a Teradata SET table; an identical row (NULLs compare equal in the duplicate-row check) failed with error 2802. EQUAL_NULL reproduces the NULL-equal comparison.
    SELECT COUNT(*) INTO :dup_count
    FROM SALES.TRANSFER t
    WHERE t.TRANSFER_ID = 1
      AND EQUAL_NULL(t.FROM_ACCOUNT, CAST(:P_FROM AS NUMBER(19,0)))
      AND EQUAL_NULL(t.TO_ACCOUNT, CAST(:P_TO AS NUMBER(19,0)));
    IF (dup_count > 0) THEN
        RAISE duplicate_transfer;
    END IF;

    -- Converted: INSERT INTO sales.transfer ... VALUES (1, p_from, p_to) -> same insert with bind variables and explicit casts
    -- Reason: Parameters are referenced as :NAME in Snowflake Scripting SQL; casts keep the source types.
    INSERT INTO SALES.TRANSFER (TRANSFER_ID, FROM_ACCOUNT, TO_ACCOUNT)
    VALUES (CAST(1 AS NUMBER(19,0)), CAST(:P_FROM AS NUMBER(19,0)), CAST(:P_TO AS NUMBER(19,0)));

    -- Converted: SET-table duplicate-row error on SALES.AUDIT_LOG -> existence check that raises -20803
    -- Reason: SALES.AUDIT_LOG was a Teradata SET table; the transfer row is already committed when this fails, as in Teradata.
    SELECT COUNT(*) INTO :dup_count
    FROM SALES.AUDIT_LOG a
    WHERE a.EVENT_ID = 2
      AND a.EVENT_TYPE = 'TRANSFER';
    IF (dup_count > 0) THEN
        RAISE duplicate_audit;
    END IF;

    -- Converted: INSERT INTO sales.audit_log ... VALUES (2, 'TRANSFER') -> same insert with explicit casts
    -- Reason: Keeps the column types of SALES.AUDIT_LOG.
    INSERT INTO SALES.AUDIT_LOG (EVENT_ID, EVENT_TYPE)
    VALUES (CAST(2 AS NUMBER(19,0)), CAST('TRANSFER' AS VARCHAR(40)));

    RETURN NULL;
END;
$$;

-- Converted: CREATE PROCEDURE sales.repair_payment() -> CREATE PROCEDURE SALES.REPAIR_PAYMENT() RETURNS VARCHAR LANGUAGE SQL
-- Reason: Snowflake Scripting procedure; RETURNS is mandatory, so RETURN NULL stands in for no return value. Plain CREATE keeps the error if it already exists.
-- Converted: default SQL SECURITY (DEFINER) -> EXECUTE AS OWNER
-- Reason: Closest Snowflake equivalent of definer's rights; Snowflake requires the clause to be explicit.
CREATE PROCEDURE SALES.REPAIR_PAYMENT()
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS
$$
DECLARE
    unconverted_statement EXCEPTION (-20900, 'SALES.REPAIR_PAYMENT: source statement 1 is an empty, invalid SELECT and was not converted; manual remediation required');
    dup_count NUMBER(38,0) DEFAULT 0;
    duplicate_audit EXCEPTION (-20802, 'Duplicate row in SET table SALES.AUDIT_LOG (EVENT_ID 3, EVENT_TYPE REPAIR)');
BEGIN
    -- Converted: invalid source statement (SELECT with no select list and no table) -> RAISE unconverted_statement
    -- Reason: The source statement is syntactically invalid (Teradata could not compile this procedure), so its intent is unknown. Failing closed keeps the audit row from being written by a half-converted repair routine.
    RAISE unconverted_statement;

    -- Converted: SET-table duplicate-row error on SALES.AUDIT_LOG -> existence check that raises -20802
    -- Reason: SALES.AUDIT_LOG was a Teradata SET table; an identical row raised error 2802.
    SELECT COUNT(*) INTO :dup_count
    FROM SALES.AUDIT_LOG a
    WHERE a.EVENT_ID = 3
      AND a.EVENT_TYPE = 'REPAIR';
    IF (dup_count > 0) THEN
        RAISE duplicate_audit;
    END IF;

    -- Converted: INSERT INTO sales.audit_log ... VALUES (3, 'REPAIR') -> same insert with explicit casts
    -- Reason: Keeps the column types of SALES.AUDIT_LOG; this code runs only after the unconverted statement above is fixed.
    INSERT INTO SALES.AUDIT_LOG (EVENT_ID, EVENT_TYPE)
    VALUES (CAST(3 AS NUMBER(19,0)), CAST('REPAIR' AS VARCHAR(40)));

    RETURN NULL;
END;
$$;
